    const n = chunk.length;
    if (n === 0) return records;
    let i = 0;
    if (!started) {
      started = true;
      if (chunk.charCodeAt(0) === 0xfeff) i = 1;
    }

    while (i < n) {
      if (state === QUOTED) {
        let j = i;
        for (; j < n; j++) {
          const c = chunk[j];
          if (c === '"') break;
          if (c === '\r') {
            line++;
            lastWasCR = true;
          } else {
            if (c === '\n' && !lastWasCR) line++;
            lastWasCR = false;
          }
        }
        field += chunk.slice(i, j);
        if (j < n) {
          state = QUOTE_SEEN;
          lastWasCR = false;
          j++;
        }
        i = j;
        continue;
      }

      if (state === UNQUOTED) {
        let j = i;
        while (j < n) {
          const c = chunk[j];
          if (c === delimiter || c === '\n' || c === '\r') break;
          j++;
        }
        field += chunk.slice(i, j);
        i = j;
        if (i === n) break;
      }

      const c = chunk[i++];
      if (state === QUOTE_SEEN) {
        if (c === '"') {
          field += '"';
          state = QUOTED;
          continue;
        }
        if (c !== delimiter && c !== '\n' && c !== '\r') {
          throw new SyntaxError(`Unexpected character after closing quote at line ${line}`);
