          lastWasCR = false;
          continue;
        }
        if (c === '"') {
          state = QUOTED;
          inRecord = true;
          lastWasCR = false;
          continue;
        }
      }

      if (c === delimiter) {
        row.push(field);
        field = '';
        state = FIELD_START;
        inRecord = true;
        lastWasCR = false;
      } else if (c === '\n' || c === '\r') {
        row.push(field);
        records.push(row);
        row = [];
        field = '';
        state = FIELD_START;
        inRecord = false;
        line++;
        lastWasCR = c === '\r';
      } else {
        field += c;
        state = UNQUOTED;
        inRecord = true;
        lastWasCR = false;
      }
    }
    return records;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) throw new SyntaxError(`Unterminated quoted field at line ${line}`);
    if (!inRecord) return [];
    row.push(field);
    const last = row;
    row = [];
    field = '';
    return [last];
  }

  return { push, end };
