  let field = '';
  let row = [];
  let inRecord = false; // current record has consumed at least one character
  let line = 1;
  let lastWasCR = false; // previous input character was CR (for CRLF across chunks)
  let started = false;
  let ended = false;

  function push(chunk) {
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
    if (ended) throw new Error('cannot push after end()');
