          lastWasCR = false;
          j++;
        }
        i = j;
        continue;
      }

      if (state === UNQUOTED) {
        let j = i;
        while (j < n) {
          const c = chunk[j];
          if (c === delimiter || c === '\n' || c === '\r') break;
          j++;
