'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const run = (chunks, opts) => {
  const p = createParser(opts);
  const out = [];
  for (const c of chunks) out.push(...p.push(c));
  out.push(...p.end());
  return out;
};
const err = (chunks, re) => assert.throws(() => run(chunks), e => e instanceof SyntaxError && re.test(e.message));

assert.deepEqual(parse(''), []);
assert.deepEqual(parse('\uFEFF'), []);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\n'), [['a']]);
assert.deepEqual(parse('a\r\nb\rc\nd'), [['a'], ['b'], ['c'], ['d']]);
assert.deepEqual(parse('a"b,c"\n'), [['a"b', 'c"']]);
assert.deepEqual(parse('"x\r\ny\rz",\n'), [['x\r\ny\rz', '']]);
assert.deepEqual(parse('\uFEFFa,\uFEFFb'), [['a', '\uFEFFb']]);
assert.deepEqual(parse('a;b,c', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
for (const d of ['"', '\r', '\n', '', ';;', null, 1]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.deepEqual(run(['a,b'], { delimiter: undefined }), [['a', 'b']]);

// immediate emission, CR across chunks
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push(''), []);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
assert.throws(() => createParser().push(1), TypeError);

// line numbers
err(['"a" ,b'], /line 1\b/);
err(['x\r\n"a\r\nb"x'], /line 3\b/);
err(['x\r', '\n"a\r', '\nb"x'], /line 3\b/);
err(['"a\n\rb"c'], /line 3\b/);
err(['a\n"abc\n'], /line 3\b/);

// all 2- and 3-way splits match single push
const samples = [
  '\uFEFFname,"q ""x"" y"\r\n"multi\r\nline\rz",,\r\nlast,"",""""\r',
  'a"b,"c""d"\n\n\r\r\n"",x\uD83D\uDE00y\n"\uD83D\uDE00"',
  '"x"\r\n"y"\r"z"\n',
];
for (const s of samples) {
  const whole = parse(s);
  for (let i = 0; i <= s.length; i++) {
    assert.deepEqual(run([s.slice(0, i), s.slice(i)]), whole, `split ${i}`);
    for (let j = i; j <= s.length; j++) assert.deepEqual(run([s.slice(0, i), '', s.slice(i, j), s.slice(j)]), whole);
  }
  assert.deepEqual(run([...s]), whole);
}
const bad = 'a\r\n"b\r\nc"\r\n"d\r\n" x';
for (let i = 0; i <= bad.length; i++) err([bad.slice(0, i), bad.slice(i)], /line 5\b/);

// header mode
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('x,x,__proto__\n1,2,3\n4', { header: true }), [{ x: '1', x_2: '2', ['__proto__']: '3' }, { x: '4', x_2: '', ['__proto__']: '' }].map(o => o));
const h = parse('__proto__\nv', { header: true })[0];
assert.equal(Object.getPrototypeOf(h), Object.prototype);
assert.deepEqual(Object.keys(h), ['__proto__']);
console.log('smoke ok');

